class Solution {
public:
    vector<double> sampleStats(vector<int>& count) {
        long long total = 0, sum = 0;
        int lo = -1, hi = -1, mode = 0;
        for (int i = 0; i < 256; ++i) {
            if (count[i]) {
                if (lo == -1) lo = i;
                hi = i;
            }
            if (count[i] > count[mode]) mode = i;
            total += count[i];
            sum += 1LL * i * count[i];
        }
        long long left = (total + 1) / 2, right = (total + 2) / 2;
        int m1 = -1, m2 = -1;
        long long seen = 0;
        for (int i = 0; i < 256; ++i) {
            seen += count[i];
            if (m1 == -1 && seen >= left) m1 = i;
            if (m2 == -1 && seen >= right) { m2 = i; break; }
        }
        return {double(lo), double(hi), double(sum) / total,
                (m1 + m2) / 2.0, double(mode)};
    }
};
